package org.codex.nfsugpreview;
import android.app.*;import android.os.*;import java.io.*;import java.nio.file.*;import org.json.*;
public final class IndexedSceneGpuInstrumentation extends SceneGpuInstrumentation {
 @Override public void onStart(){Bundle result=new Bundle();boolean live=false;try{
  byte[] raw=Files.readAllBytes(new File(getTargetContext().getFilesDir(),"indexed-scene-whole.nab").toPath());NativeSceneSnapshot scene=new NativeSceneSnapshot(raw);NativeSceneDrawPlan plan=new NativeSceneDrawPlan(scene.geometry(0));int indexed=0;for(int i=0;i<plan.count();i++)if(plan.draw(i).indexed)indexed++;ok(indexed==plan.count(),"Expected all synthetic draws indexed");
  startGl();live=true;String small=render(scene,240,160,240,160,"indexed-scene-240.png",false),large=render(scene,3840,2160,3240,2160,"indexed-scene-4k.png",false);ok(zeroChecks>0&&wallSkipEvaluations>0,"Indexed zero/skip path not sampled");endGl();live=false;startGl();live=true;ok(render(scene,240,160,240,160,null,false).equals(small),"Indexed context changed pixels");
  JSONObject report=new JSONObject();report.put("result","PASS_ANDROID_INDEXED_SCENE_GLES");report.put("source_commands",plan.count());report.put("indexed_commands",indexed);report.put("renderer",renderer);report.put("api",Build.VERSION.SDK_INT);report.put("source_pixel_checks",checks);report.put("zero_index_evaluations",zeroChecks);report.put("wall_skip_evaluations",wallSkipEvaluations);report.put("native_rgba_sha256",small);report.put("four_k_frame_sha256",large);report.put("synthetic_materials",true);report.put("per_row_palette_variants",160);report.put("context_recreated",true);report.put("full_scene",false);report.put("real_time_pacing",false);try(FileOutputStream out=getTargetContext().openFileOutput("indexed-scene-report.json",0)){out.write(report.toString(2).getBytes("UTF-8"));}result.putString("stream",report.toString());finish(Activity.RESULT_OK,result);
 }catch(Throwable e){android.util.Log.e("NFSUGSceneGPU","Failed",e);result.putString("stream","FAIL: "+e);finish(Activity.RESULT_CANCELED,result);}finally{if(live)endGl();}}
}
